<?php defined( 'ABSPATH' ) || exit;
$owner = ! empty( $owner );
$id = (int) ( $review['id'] ?? 0 );
$review_status = $review['status'] ?? 'pending';
$published = 'published' === $review_status;
$tier_key = $review['tier']['key'] ?? 'member';
?>
<article class="pcr-review" id="pcr-review-<?php echo esc_attr( $id ); ?>">
    <header class="pcr-review-head"><?php echo Petish_Customer_Reviews_UI::avatar( $review ); ?><div class="pcr-review-identity"><strong><?php echo esc_html( $review['alias'] ?? '' ); ?></strong><p class="pcr-small"><span class="pcr-tier-label pcr-tier-<?php echo esc_attr( $tier_key ); ?>"><?php echo esc_html( $review['tier']['title'] ?? '' ); ?></span> · <?php echo esc_html( sprintf( _n( '%s review', '%s reviews', (int) ( $review['review_count'] ?? 0 ), 'petish-passport' ), number_format_i18n( (int) ( $review['review_count'] ?? 0 ) ) ) ); ?></p><?php if ( ! empty( $review['verified'] ) ) : ?><span class="pcr-verified"><?php esc_html_e( 'Verified purchase', 'petish-passport' ); ?></span><?php endif; ?></div><div class="pcr-review-score"><?php echo Petish_Customer_Reviews_UI::stars( $review['rating'] ?? 0 ); ?><time datetime="<?php echo esc_attr( $review['date'] ?? '' ); ?>"><?php echo esc_html( $review['date_label'] ?? '' ); ?></time></div></header>
    <?php if ( $owner ) : ?><p class="pcr-small"><a href="<?php echo esc_url( $review['product_url'] ?? '' ); ?>"><?php echo esc_html( $review['product_name'] ?? '' ); ?></a> · <span class="pcr-status"><?php echo esc_html( array( 'published' => __( 'Published', 'petish-passport' ), 'pending' => __( 'Awaiting moderation', 'petish-passport' ), 'withdrawn' => __( 'Withdrawn', 'petish-passport' ), 'rejected' => __( 'Not published', 'petish-passport' ) )[ $review_status ] ?? __( 'Not published', 'petish-passport' ) ); ?></span></p><?php endif; ?>
    <h3><?php echo esc_html( $review['title'] ?? '' ); ?></h3><div class="pcr-review-body"><?php echo wpautop( esc_html( $review['body'] ?? '' ) ); ?></div>
    <?php Petish_Customer_Reviews_UI::media( $review['media'] ?? array() ); ?>
    <p class="pcr-disclosure"><?php esc_html_e( 'This contribution counts towards reviewer status. Discount and delivery rewards are not active.', 'petish-passport' ); ?></p>
    <?php if ( $published ) : ?><div class="pcr-review-actions"><div class="pcr-votes" aria-label="<?php esc_attr_e( 'Feedback received on this review', 'petish-passport' ); ?>">
        <?php foreach ( array( 'helpful' => __( 'Helpful', 'petish-passport' ), 'not-helpful' => __( 'Not helpful', 'petish-passport' ) ) as $choice => $label ) : $amount = (int) ( $review[ 'helpful' === $choice ? 'helpful' : 'not_helpful' ] ?? 0 ); $selected = ( $review['own_vote'] ?? '' ) === $choice; ?>
            <?php if ( ! $owner && ! empty( $review['can_vote'] ) && is_user_logged_in() ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="petish_customer_review_vote"><input type="hidden" name="review_id" value="<?php echo esc_attr( $id ); ?>"><input type="hidden" name="choice" value="<?php echo esc_attr( $selected ? 'none' : $choice ); ?>"><?php Petish_Customer_Reviews_UI::nonce( 'vote', $id ); ?><button type="submit" class="pcr-vote" aria-pressed="<?php echo $selected ? 'true' : 'false'; ?>"><?php echo esc_html( $label ); ?> <strong><?php echo esc_html( number_format_i18n( $amount ) ); ?></strong></button></form>
            <?php else : ?><span class="pcr-vote pcr-vote-count"><?php echo esc_html( $label ); ?> <strong><?php echo esc_html( number_format_i18n( $amount ) ); ?></strong></span><?php endif; ?>
        <?php endforeach; ?>
        <?php if ( ! $owner && ! is_user_logged_in() ) : ?><a class="pcr-small" href="<?php echo esc_url( wp_login_url( ( $review['product_url'] ?? '' ) . '#pcr-review-' . $id ) ); ?>"><?php esc_html_e( 'Sign in to react', 'petish-passport' ); ?></a><?php endif; ?>
        </div><?php if ( ! $owner && is_user_logged_in() && ! empty( $review['can_vote'] ) ) : ?><details class="pcr-report"><summary><?php esc_html_e( 'Report', 'petish-passport' ); ?></summary><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="petish_customer_review_report"><input type="hidden" name="review_id" value="<?php echo esc_attr( $id ); ?>"><?php Petish_Customer_Reviews_UI::nonce( 'report', $id ); ?><label><?php esc_html_e( 'Reason', 'petish-passport' ); ?><select name="reason"><option value="privacy"><?php esc_html_e( 'Privacy concern', 'petish-passport' ); ?></option><option value="abuse"><?php esc_html_e( 'Abusive or misleading content', 'petish-passport' ); ?></option><option value="unsafe"><?php esc_html_e( 'Unsafe advice', 'petish-passport' ); ?></option><option value="other"><?php esc_html_e( 'Other concern', 'petish-passport' ); ?></option></select></label><button class="pcr-button pcr-secondary" type="submit"><?php esc_html_e( 'Send report', 'petish-passport' ); ?></button></form></details><?php endif; ?></div><?php endif; ?>
    <?php if ( $owner && in_array( $review_status, array( 'published', 'pending' ), true ) ) : ?><details class="pcr-withdraw"><summary><?php esc_html_e( 'Withdraw this review', 'petish-passport' ); ?></summary><p class="pcr-small"><?php esc_html_e( 'The review and its media will no longer be public. Your qualifying review count and status may change.', 'petish-passport' ); ?></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="petish_customer_review_withdraw"><input type="hidden" name="review_id" value="<?php echo esc_attr( $id ); ?>"><?php Petish_Customer_Reviews_UI::nonce( 'withdraw', $id ); ?><label class="pcr-check"><input type="checkbox" name="confirm" value="1" required><span><?php esc_html_e( 'I want to withdraw this review.', 'petish-passport' ); ?></span></label><button class="pcr-button pcr-secondary" type="submit"><?php esc_html_e( 'Confirm withdrawal', 'petish-passport' ); ?></button></form></details><?php endif; ?>
</article>
